/**
 * PLACEHOLDER ART — avatar sprite sheet generated by code, to be replaced by
 * the final layered avatars. The character is original and deliberately simple.
 *
 * Sheet layout: one row per direction, four walk frames per row.
 * Frame 0 doubles as the idle pose.
 */
import type { CanvasTexture } from 'three';
import { createPixelTexture, outlineSprite } from '../scene/placeholder-textures';

export type AvatarDirection = 'down' | 'left' | 'right' | 'up';

export const AVATAR_FRAME = { width: 24, height: 36 };
export const AVATAR_WALK_FRAMES = 4;
export const AVATAR_DIRECTIONS: readonly AvatarDirection[] = ['down', 'left', 'right', 'up'];

/** Colours of the avatar. Changing them recolours the sprite without redrawing it. */
export interface AvatarPalette {
  skin: string;
  hair: string;
  shirt: string;
  trousers: string;
  shoes: string;
}

export const PLACEHOLDER_AVATAR_PALETTE: AvatarPalette = {
  skin: '#f2c9a0',
  hair: '#5b3a29',
  shirt: '#d9534f',
  trousers: '#3b4a7a',
  shoes: '#2b2233',
};

const EYE_COLOR = '#2a2233';
const OUTLINE_COLOR: [number, number, number] = [34, 24, 40];

/** Darkens a #rrggbb colour by the given factor (0 = black, 1 = unchanged). */
function darken(hex: string, factor: number): string {
  const channel = (start: number) =>
    Math.round(parseInt(hex.slice(start, start + 2), 16) * factor)
      .toString(16)
      .padStart(2, '0');
  return `#${channel(1)}${channel(3)}${channel(5)}`;
}

function drawFrame(
  ctx: CanvasRenderingContext2D,
  originX: number,
  originY: number,
  direction: AvatarDirection,
  frame: number,
  palette: AvatarPalette,
): void {
  // The right-facing pose is the left-facing one mirrored.
  const mirrored = direction === 'right';
  const rect = (color: string, x: number, y: number, width: number, height: number) => {
    ctx.fillStyle = color;
    ctx.fillRect(originX + (mirrored ? AVATAR_FRAME.width - x - width : x), originY + y, width, height);
  };

  const stepping = frame % 2 === 1;
  /** The upper body drops by one pixel on each step. */
  const bob = stepping ? 1 : 0;
  /** +1 on the first step, -1 on the second, 0 when the legs pass each other. */
  const swing = frame === 1 ? 1 : frame === 3 ? -1 : 0;
  const shirtShade = darken(palette.shirt, 0.8);
  const trousersShade = darken(palette.trousers, 0.8);
  const hairShade = darken(palette.hair, 0.8);

  if (direction === 'down' || direction === 'up') {
    // Legs: the stepping leg is lifted (shorter).
    const leftLift = swing === 1 ? 2 : 0;
    const rightLift = swing === -1 ? 2 : 0;
    rect(palette.trousers, 8, 22, 4, 10 - leftLift);
    rect(palette.shoes, 8, 32 - leftLift, 4, 2);
    rect(trousersShade, 12, 22, 4, 10 - rightLift);
    rect(palette.shoes, 12, 32 - rightLift, 4, 2);
    // Torso
    rect(palette.shirt, 7, 12 + bob, 10, 10 - bob);
    rect(shirtShade, 15, 12 + bob, 2, 10 - bob);
    // Arms swing opposite to the legs
    rect(palette.shirt, 5, 12 + bob - swing, 2, 6);
    rect(palette.skin, 5, 18 + bob - swing, 2, 2);
    rect(shirtShade, 17, 12 + bob + swing, 2, 6);
    rect(palette.skin, 17, 18 + bob + swing, 2, 2);
    // Head
    rect(palette.skin, 7, 4 + bob, 10, 8);
    if (direction === 'down') {
      rect(palette.hair, 6, 2 + bob, 12, 4);
      rect(palette.hair, 6, 6 + bob, 1, 3);
      rect(palette.hair, 17, 6 + bob, 1, 3);
      rect(hairShade, 7, 6 + bob, 2, 1);
      rect(hairShade, 15, 6 + bob, 2, 1);
      rect(EYE_COLOR, 9, 8 + bob, 1, 2);
      rect(EYE_COLOR, 14, 8 + bob, 1, 2);
    } else {
      rect(palette.hair, 6, 2 + bob, 12, 9);
      rect(hairShade, 6, 9 + bob, 12, 2);
    }
    return;
  }

  // Side view (drawn facing left)
  if (stepping) {
    // Legs apart; which one is in front alternates between the two steps.
    rect(swing === 1 ? palette.trousers : trousersShade, 7, 22, 4, 9);
    rect(palette.shoes, 6, 31, 5, 2);
    rect(swing === 1 ? trousersShade : palette.trousers, 13, 22, 4, 9);
    rect(palette.shoes, 12, 31, 5, 2);
  } else {
    rect(palette.trousers, 9, 22, 6, 10);
    rect(palette.shoes, 8, 32, 7, 2);
  }
  // Torso
  rect(palette.shirt, 8, 12 + bob, 8, 10 - bob);
  rect(shirtShade, 14, 12 + bob, 2, 10 - bob);
  // Arm swinging back and forth
  rect(shirtShade, 10 + swing * 2, 13 + bob, 3, 6);
  rect(palette.skin, 10 + swing * 2, 19 + bob, 3, 2);
  // Head: face on the left, hair on top and at the back
  rect(palette.skin, 7, 4 + bob, 10, 8);
  rect(palette.hair, 6, 2 + bob, 12, 4);
  rect(palette.hair, 12, 6 + bob, 6, 5);
  rect(hairShade, 12, 9 + bob, 6, 2);
  rect(EYE_COLOR, 8, 8 + bob, 1, 2);
}

/** Builds the full sprite sheet for one avatar palette. */
export function createPlaceholderAvatarTexture(
  palette: AvatarPalette = PLACEHOLDER_AVATAR_PALETTE,
): CanvasTexture {
  const texture = createPixelTexture(
    AVATAR_FRAME.width * AVATAR_WALK_FRAMES,
    AVATAR_FRAME.height * AVATAR_DIRECTIONS.length,
    (ctx) => {
      AVATAR_DIRECTIONS.forEach((direction, row) => {
        for (let frame = 0; frame < AVATAR_WALK_FRAMES; frame++) {
          drawFrame(ctx, frame * AVATAR_FRAME.width, row * AVATAR_FRAME.height, direction, frame, palette);
        }
      });
      outlineSprite(ctx, OUTLINE_COLOR);
    },
  );
  texture.repeat.set(1 / AVATAR_WALK_FRAMES, 1 / AVATAR_DIRECTIONS.length);
  return texture;
}

/** Points the texture at one frame of the sheet. */
export function selectAvatarFrame(texture: CanvasTexture, direction: AvatarDirection, frame: number): void {
  const row = AVATAR_DIRECTIONS.indexOf(direction);
  texture.offset.set(
    (frame % AVATAR_WALK_FRAMES) / AVATAR_WALK_FRAMES,
    1 - (row + 1) / AVATAR_DIRECTIONS.length,
  );
}
